このタスクを理解しました。'rushZefFen' operation を追加する必要があります。これは Zef と Fen を同時に 'nim' から 'dor' へ直接進める操作です。

まず、リポジトリの構造を確認して、必要な変更を実装します。

<modified_files>
{
  "src/vok/rules.ts": "// Rules for the world protocol

export interface Entity {
  id: string;
  state: string;
}

export interface Operation {
  type: string;
  targetId?: string;
  [key: string]: any;
}

export interface WorldState {
  entities: Map<string, Entity>;
}

// Entity state transitions
export const ENTITY_TRANSITIONS: Record<string, string[]> = {
  nim: ['pex', 'dor'],
  pex: ['dor'],
  dor: [],
};

// Special operations that bypass normal transitions
export const SPECIAL_OPERATIONS: Record<string, (state: WorldState, op: Operation) => boolean> = {
  rushZefFen: (state: WorldState, op: Operation): boolean => {
    // Check if both Zef and Fen exist and are in 'nim' state
    const zefEntity = state.entities.get('Zef');
    const fenEntity = state.entities.get('Fen');

    if (!zefEntity || !fenEntity) {
      return false;
    }

    if (zefEntity.state !== 'nim' || fenEntity.state !== 'nim') {
      return false;
    }

    // Move both to 'dor' state directly
    zefEntity.state = 'dor';
    fenEntity.state = 'dor';

    return true;
  },
};

// Standard operation: moveEntity
export function canMoveEntity(state: WorldState, entityId: string, targetState: string): boolean {
  const entity = state.entities.get(entityId);

  if (!entity) {
    return false;
  }

  const currentTransitions = ENTITY_TRANSITIONS[entity.state];
  return currentTransitions && currentTransitions.includes(targetState);
}

export function moveEntity(state: WorldState, entityId: string, targetState: string): boolean {
  if (!canMoveEntity(state, entityId, targetState)) {
    return false;
  }

  const entity = state.entities.get(entityId);
  if (entity) {
    entity.state = targetState;
    return true;
  }

  return false;
}
",
  "src/protocol_adapter.ts": "import { Entity, Operation, WorldState, SPECIAL_OPERATIONS, moveEntity } from './vok/rules';

export interface WorldProtocol {
  reset(): void;
  applyOperation(operation: Operation): boolean;
  getEntityState(entityId: string): string | null;
  toAbstractSnapshot(): Record<string, string>;
}

// Internal state
let worldState: WorldState = {
  entities: new Map(),
};

// Initialize default entities
function initializeWorld(): void {
  worldState.entities.clear();
  worldState.entities.set('Zef', { id: 'Zef', state: 'nim' });
  worldState.entities.set('Fen', { id: 'Fen', state: 'nim' });
}

// Protocol implementation
export const protocol: WorldProtocol = {
  reset(): void {
    initializeWorld();
  },

  applyOperation(operation: Operation): boolean {
    // Check for special operations first
    if (operation.type === 'rushZefFen') {
      const specialHandler = SPECIAL_OPERATIONS['rushZefFen'];
      if (specialHandler) {
        return specialHandler(worldState, operation);
      }
      return false;
    }

    // Handle standard moveEntity operation
    if (operation.type === 'moveEntity') {
      const { targetId, targetState } = operation;
      if (!targetId || !targetState) {
        return false;
      }
      return moveEntity(worldState, targetId, targetState);
    }

    return false;
  },

  getEntityState(entityId: string): string | null {
    const entity = worldState.entities.get(entityId);
    return entity ? entity.state : null;
  },

  toAbstractSnapshot(): Record<string, string> {
    const snapshot: Record<string, string> = {};
    for (const [id, entity] of worldState.entities) {
      snapshot[id] = entity.state;
    }
    return snapshot;
  },
};

// Initialize on module load
initializeWorld();
"
}
